    const result = calculateDiscount(test.inputPrice ?? 10, test.inputQuantity);

    if (result === test.expected) {
        console.log(`PASS: ${test.description}`);
    } else {
        console.log(`FAIL: ${test.description} (expected: ${test.expected}, got: ${result})`);
    }
