import { readFileSync } from 'node:fs';

// Check command-line arguments for the file path, default to 'input/text.txt'
const filePath = process.argv[2] || 'input/text.txt';

try {
  // Read the file content as a UTF-8 string
  const textContent = readFileSync(filePath, 'utf8');

  // Convert to lowercase and replace all non-letter characters with spaces.
  // This effectively strips punctuation while preserving word structure.
  const processedText = textContent.toLowerCase().replace(/[^a-z]/g, ' ');

  // Split the text into words by whitespace (handles multiple spaces/newlines)
  // Filter out empty strings resulting from consecutive spaces or end of string
  const words: string[] = processedText.split(' ').filter((word) => word.length > 0);

  // Count frequency of each word using a Map
  const wordCounts = new Map<string, number>();
  for (const word of words) {
    const currentCount = wordCounts.get(word) || 0;
    wordCounts.set(word, currentCount + 1);
  }

  // Convert the map to an array of entries [word, count]
  const uniqueWords = Array.from(wordCounts.entries());

  // Sort by frequency (descending) first, then alphabetically (ascending)
  uniqueWords.sort((a, b) => {
    if (a[1] !== b[1]) {
      return b[1] - a[1]; // Higher count first (descending)
    } else {
      return a[0].localeCompare(b[0]); // Alphabetically ascending for ties
    }
  });

  // Output the formatted results to stdout
  for (const [word, count] of uniqueWords) {
    console.log(`${word}: ${count}`);
  }
} catch (error) {
  // Handle file access errors gracefully. 
  // No explicit error message to stdout per "Do not output anything else" rule for valid inputs.
  // However, on failure, we cannot produce the output list anyway.
  process.exitCode = 1;
}
